interface Button { render(): void }
interface Checkbox { render(): void }

class WinButton implements Button { render() { /* win draw */ } }
class WinCheckbox implements Checkbox { render() { /* win draw */ } }

interface GUIFactory { createButton(): Button; createCheckbox(): Checkbox }
class WinFactory implements GUIFactory { createButton() { return new WinButton() } createCheckbox() { return new WinCheckbox() } }

interface GUIFactory { createButton(): Button; createCheckbox(): Checkbox }

// New product type Slider added later
interface GUIFactoryV2 { createButton(): Button; createCheckbox(): Checkbox; createSlider(): Slider }

// Many concrete factories must implement GUIFactoryV2

// Version A: plugin modules register family factories
const registry = new Map<string, GUIFactory>()
// plugin A registers: registry.set('win', new WinFactory())
// plugin B registers: registry.set('mac', new MacFactory())

// Version B: single central factory with conditionals
class CentralFactory { create(kind, product) { if(kind==='win') { if(product==='button') return new WinButton() } /* many conditionals */ } }
